import json, re

def parse_version(v):
    m = re.match(r'^(\d+)\.(\d+)\.(\d+)(?:-(.+))?$', v)
    major, minor, patch, pre = int(m.group(1)), int(m.group(2)), int(m.group(3)), m.group(4)
    return (major, minor, patch, 0 if pre is None else -1, pre or '')

def cmp(a, b):
    pa, pb = parse_version(a), parse_version(b)
    return (pa > pb) - (pa < pb)

def in_range(version, range_str):
    for part in range_str.split():
        m = re.match(r'^(>=|>|<=|<)(.+)$', part)
        op, bound = m.group(1), m.group(2)
        c = cmp(version, bound)
        if op == '>=' and c < 0: return False
        if op == '>' and c <= 0: return False
        if op == '<=' and c > 0: return False
        if op == '<' and c >= 0: return False
    return True

sbom = json.load(open('/app/sbom.json'))
advisories = json.load(open('/app/advisories.json'))

affected = []
for comp in sbom['components']:
    for adv in advisories['advisories']:
        if adv['ecosystem'] != comp['ecosystem'] or adv['package'] != comp['name']:
            continue
        if any(in_range(comp['version'], r) for r in adv['ranges']):
            affected.append({
                'component': comp['name'],
                'ecosystem': comp['ecosystem'],
                'version': comp['version'],
                'purl': comp['purl'],
                'advisory_id': adv['id'],
                'severity': adv['severity'],
                'fixed_version': adv['fixed_version'],
            })

affected.sort(key=lambda x: (x['component'], x['advisory_id']))
result = {'affected_count': len(affected), 'affected': affected}
open('/app/vulnerabilities.json', 'w').write(json.dumps(result, indent=2) + '\n')
print(json.dumps(result, indent=2))

